async function clear(){if(!confirm('Clear this portfolio from this browser? Export a backup first if needed.'))return;secureSession.clear();brokerSession=null;try{await forgetSavedConnection();}catch(e){notice('Could not forget the saved connection: '+e.message);return;}state.transactions=[];state.xtbAccounts=[];state.performance=[];state.assetNames={};state.demo=false;accountFilter='all';delete state.broker;brokerError='';quotes={};save();render();}
$('.nav').parentNode.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;filter='';render();}});
$('#xtb-import-header').onclick=openXtb;$('#refresh').onclick=refresh;$('#currency').onchange=()=>{state.base=$('#currency').value;save();render();refresh();};$('#export').onclick=backup;$('#start-empty').onclick=clear;
$('#add').onclick=()=>{$('#transaction-form').reset();$('#transaction-form').elements.date.value=today();$('#form-error').textContent='';$('#transaction-dialog').showModal();};$('#close-dialog').onclick=()=>$('#transaction-dialog').close();
$('#transaction-form').onsubmit=e=>{e.preventDefault();try{const t=validateTransaction(Object.fromEntries(new FormData(e.target)));const next=[...state.transactions,t];ledger(next);state.transactions=next;save();$('#transaction-dialog').close();render();refresh();toast('Transaction saved');}catch(err){$('#form-error').textContent=err.message;}};
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('Maximum import size is 2 MB.');const text=await file.text();let next,accountRegistry=state.demo?[]:registeredXtbAccounts();if(file.name.endsWith('.json')){const data=JSON.parse(text);if(data.version!==1||!Array.isArray(data.transactions))throw Error('Unsupported backup format.');next=data.transactions.map(validateTransaction);accountRegistry=(Array.isArray(data.xtbAccounts)?data.xtbAccounts:[]).map(a=>{const details=xtbAccountDetails(a?.accountId);return details?.currency?{accountId:a.accountId,...details}:null;}).filter(Boolean);if(!confirm(`Replace all records with ${next.length} transactions from this backup?`))return;}else {const imported=parseCSV(text);if(state.demo){if(!confirm(`Replace example data with ${imported.length} imported transactions?`))return;next=imported;}else{if(!confirm(`Append ${imported.length} transactions? Re-importing the same CSV creates duplicates.`))return;next=[...state.transactions,...imported];}}if(next.length>10000)throw Error('Maximum 10,000 records.');ledger(next);const ids=new Set();for(const t of next){if(typeof t.id!=='string'||ids.has(t.id))t.id=crypto.randomUUID();ids.add(t.id);}state.transactions=next;state.xtbAccounts=accountRegistry;state.performance=[];state.demo=false;delete state.broker;secureSession.clear();brokerSession=null;brokerError='';quotes={};save();render();refresh();toast('Import complete. Reconnect brokers to restore snapshots.');}catch(err){toast(err.message);}finally{e.target.value='';}};


function initTheme(){let theme='dark';try{theme=localStorage.getItem('folio.theme')||'dark';}catch{}const apply=()=>{document.documentElement.dataset.theme=theme;$('#theme-toggle').textContent=theme==='dark'?'☀':'☾';$('#theme-toggle').setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} theme`);};apply();$('#theme-toggle').onclick=()=>{theme=theme==='dark'?'light':'dark';try{localStorage.setItem('folio.theme',theme);}catch{}apply();};}
function brokerRows(){const b=state.broker;if(!b?.positions)return [];return b.positions.map(p=>({...p,symbol:b.mappings?.[p.brokerTicker]||marketSymbol(p.brokerTicker,p)||p.marketSymbol||p.brokerTicker.replaceAll('_','-').toUpperCase(),marketSymbol:b.mappings?.[p.brokerTicker]||marketSymbol(p.brokerTicker,p)||p.marketSymbol,source:'trading212'}));}
function seedBrokerQuotes(){for(const p of brokerRows()){const old=quotes[p.symbol];quotes[p.symbol]={...old,symbol:p.symbol,name:p.name,currency:p.currency,price:p.currentPrice,asOf:state.broker.syncedAt,fetchedAt:state.broker.syncedAt,source:'Trading 212 position snapshot',stale:Date.now()-Date.parse(state.broker.syncedAt)>15*60000,dividends:old?.dividends||[],history:old?.history||[]};}}
function connectionsView(){const b=state.broker;return `<div class="two-col"><div class="panel connection-panel"><div class="panel-head"><div class="broker-heading"><span class="broker-logo">212</span><div><h2>Trading 212</h2><p class="muted">Invest & Stocks ISA</p></div></div><span class="pill ${brokerSession?'':'estimated'}">${brokerSession?'Session connected':b?'Saved snapshot':'API available'}</span></div><p class="health-text">Connect open positions and received dividend payments. Create an API key in Trading 212 with account, portfolio and history <strong>read permissions</strong>. If your account uses the legacy API response, Metadata read permission is also needed to identify trading currencies. Use the API secret, not your account password.</p>${b?`<div class="broker-summary"><span class="pill">${esc(b.environment.toUpperCase())}</span><span class="pill">${b.positions.length} positions</span><span class="pill">${state.transactions.filter(t=>t.source==='trading212').length} payments</span></div><p class="connection-meta">Snapshot: ${esc(new Date(b.syncedAt).toLocaleString())}<br>${brokerSession?'Auto-sync every 5 minutes while visible.':brokerSaved.saved?'A saved connection is available; sync to reconnect.':'Reconnect after reloading to resume sync. The saved snapshot is not a live connection.'}</p>`:''}<form id="broker-form" class="broker-form" autocomplete="off"><label>Account environment<select name="environment"><option value="live" ${b?.environment==='demo'?'':'selected'}>Live account</option><option value="demo" ${b?.environment==='demo'?'selected':''}>Demo / paper account</option></select></label><label>API key<input name="apiKey" type="password" autocomplete="off" required maxlength="512" placeholder="Trading 212 API key"></label><label>API secret<input name="apiSecret" type="password" autocomplete="off" required maxlength="512" placeholder="Trading 212 API secret"></label><label class="remember-connection"><input type="checkbox" name="remember" ${brokerSaved.available?'checked':'disabled'}> Remember this connection securely ${brokerSaved.saved?'<span class="pill">Saved</span>':''}</label><div class="read-only-note">Without Remember connection, credentials are held only in memory for this page session. They are sent to this app’s server over HTTPS, used for read-only requests, and never saved in browser storage, backups or logs. When Remember connection is enabled, credentials are encrypted in your private server vault and restored after sign-in. They are never returned to this browser or included in portfolio backups.</div><button class="primary wide" ${brokerBusy?'disabled':''}>${brokerBusy?'Connecting…':brokerSession?'Reconnect with credentials':'Connect Trading 212'}</button></form>${brokerSaved.saved&&!b?'<button type="button" id="forget-vault" class="secondary danger">Forget saved connection</button>':''}<div id="broker-status" class="broker-status ${brokerError?'broker-error':''}" role="status">${esc(brokerError)}</div>${b?`<div class="broker-actions"><button id="sync-broker" class="secondary" ${!brokerSession||brokerBusy?'disabled':''}>↻ Sync now</button>${b.nextCursor?`<button id="older-dividends" class="secondary" ${!brokerSession||brokerBusy?'disabled':''}>Load older dividends</button>`:''}<button id="disconnect-broker" class="secondary danger">Disconnect & remove snapshot</button></div>`:''}<p class="annual-note">First sync loads the latest 50 payment events. Use “Load older dividends” for earlier pages; overlapping pages are deduplicated. Snapshot holdings are separate from manual transactions. Avoid entering the same positions twice. ${b?.dividendError?esc(b.dividendError):''}</p><p class="health-text"><a href="https://docs.trading212.com/api" target="_blank" rel="noreferrer">API documentation ↗</a></p></div><div class="panel connection-panel"><div class="panel-head"><div class="broker-heading"><span class="broker-logo xtb">xtb</span><div><h2>XTB</h2><p class="muted">Statement import</p></div></div><span class="pill">IKE + Regular</span></div><p class="health-text">Select multiple Excel (.xlsx) or Cash Operations CSV statements, or choose a folder to find XTB exports automatically. IKE and regular accounts are tracked separately, including holdings and dividend income.</p><div class="read-only-note">In XTB web: choose your account → Historia / History → export the full Cash Operations history to Excel. Export your IKE and regular accounts separately. Files are processed on this device.</div><div class="broker-actions"><button class="primary" id="xtb-open">↑ Import statements or folder</button></div><p class="annual-note">Preview every import before saving. Overlapping exports are deduplicated per account. Unsupported rows and missing history are reported. PDF reports and position-only workbooks cannot reconstruct a trade ledger.</p><p class="health-text"><a href="https://www.xtb.com/pl/centrum-pomocy/platformy-tradingowe-5/historia-pozycji-oraz-operacji-gotowkowych-web-i-aplikacja-mobilna" target="_blank" rel="noreferrer">XTB export instructions ↗</a></p></div></div>${b?`<div class="panel"><div class="panel-head"><div><h2>Market-data symbol mapping</h2><p class="muted">Broker quotes work without mappings. Add Yahoo symbols for history and dividend forecasts.</p></div><span class="pill">${b.positions.filter(p=>!b.mappings?.[p.brokerTicker]&&!p.marketSymbol).length} need mapping</span></div><p class="annual-note">Simple US stock symbols map automatically. For other exchanges, verify the exchange and trading currency yourself (e.g. VUSA.L or VWCE.DE). Unmapped instruments retain broker prices but have no market-history forecast. Saved mappings apply on the next refresh.</p>${b.positions.map(p=>`<label class="mapping-row"><span><strong>${esc(p.brokerTicker)}</strong><small class="small-date">${esc(p.name)} · ${esc(p.currency)} · ${num(p.quantity)} shares</small></span><input data-map="${esc(p.brokerTicker)}" value="${esc(b.mappings?.[p.brokerTicker]||marketSymbol(p.brokerTicker,p)||p.marketSymbol||'')}" aria-label="Market symbol for ${esc(p.brokerTicker)}" placeholder="e.g. VWCE.DE" maxlength="25"></label>`).join('')}<div class="broker-actions"><button class="primary" id="save-mappings">Save mappings</button></div></div>`:''}`;}
async function brokerAPI(body){const controller=new AbortController(),untrack=secureSession.track(controller);try{const r=await fetch('/api/brokers/trading212',{method:'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(55000)])});const data=await r.json();if(!r.ok){const error=Error(data.error||'Broker request failed');error.status=r.status;throw error;}return data;}finally{untrack();}}

function mergeBrokerDividends(items){const byId=new Map(state.transactions.map(t=>[t.id,t]));for(const item of items){const mapped=state.broker?.mappings?.[item.brokerTicker];const t=validateTransaction({...item,symbol:mapped||item.symbol});byId.set(t.id,t);}state.transactions=[...byId.values()];}
async function syncBroker(credentials=brokerSession){const generation=secureSession.version;if(!credentials||brokerBusy)return;if(Date.now()-brokerLastAttempt<10000){toast('Wait 10 seconds between broker requests.');return;}brokerBusy=true;brokerLastAttempt=Date.now();brokerError='';if(view==='connections')render();try{const result=await brokerAPI({...credentials,action:'snapshot'});if(!secureSession.current(generation))return;if(state.demo&&state.transactions.length&&!confirm('Replace the example portfolio with your real broker snapshot?'))return;
 result.dividends.items=result.dividends.items.map(validateTransaction);
 const old=state.broker;const same=old&&old.accountId===result.accountId&&old.environment===result.environment;if(old&&!same&&!confirm('Replace the connected broker account and its imported payments?'))return;
 if(credentials.remember!=='on'&&!credentials.useSaved&&brokerSaved.saved)await forgetSavedConnection();
 if(credentials.remember==='on'){brokerSaved=await brokerAPI({...credentials,action:'remember',revision:brokerSaved.revision});if(!secureSession.current(generation))return;}
 if(state.demo)state.transactions=[];else if(old&&!same)state.transactions=state.transactions.filter(t=>t.source!=='trading212');state.demo=false;
 state.broker={...result,mappings:same?old.mappings||{}:{},nextCursor:same&&old.historyLoaded?old.nextCursor:result.dividends.nextCursor,historyLoaded:same?old.historyLoaded:false};delete state.broker.dividends;
 if(!secureSession.connected(credentials.remember==='on'?{useSaved:true}:credentials,generation))return;brokerSession=secureSession.credentials;mergeBrokerDividends(result.dividends.items);if(result.dividendError)brokerError='Positions synced; dividend history unavailable: '+result.dividendError;save();quotes={};seedBrokerQuotes();toast('Broker snapshot synced');
 }catch(e){if(!secureSession.current(generation))return;brokerError=e.message||'Broker connection failed.';if(e.status===401||e.status===403){secureSession.clear();brokerSession=null;}}finally{brokerBusy=false;render();await refresh();}}
function bindConnections(){$('#forget-vault')?.addEventListener('click',async()=>{if(!confirm('Permanently forget the saved API credentials?'))return;secureSession.clear();brokerSession=null;try{await forgetSavedConnection();render();}catch(e){brokerError=e.message;render();}});const form=$('#broker-form');if(form)form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));form.elements.apiKey.value='';form.elements.apiSecret.value='';syncBroker(values);};$('#sync-broker')?.addEventListener('click',()=>syncBroker());$('#disconnect-broker')?.addEventListener('click',async()=>{if(!confirm('Remove the broker snapshot and its imported dividend payments? Manual records will be kept.'))return;secureSession.clear();brokerSession=null;try{await forgetSavedConnection();}catch(e){brokerError='Could not forget the saved connection: '+e.message;render();return;}brokerError='';delete state.broker;state.transactions=state.transactions.filter(t=>t.source!=='trading212');quotes={};save();render();refresh();});$('#save-mappings')?.addEventListener('click',()=>{try{const mappings={};document.querySelectorAll('[data-map]').forEach(input=>{const value=input.value.trim().toUpperCase();if(value&&!/^[A-Z0-9^][A-Z0-9.^=\-]{0,24}$/.test(value))throw Error('Enter a valid market symbol.');if(value)mappings[input.dataset.map]=value;});state.broker.mappings=mappings;for(const t of state.transactions.filter(t=>t.source==='trading212'))t.symbol=mappings[t.brokerTicker]||t.brokerTicker.replaceAll('_','-').toUpperCase();save();quotes={};render();refresh();toast('Market symbols saved');}catch(e){toast(e.message);}});
 $('#older-dividends')?.addEventListener('click',async()=>{const generation=secureSession.version;if(!brokerSession||brokerBusy)return;if(Date.now()-brokerLastAttempt<10000){toast('Wait 10 seconds between broker requests.');return;}brokerBusy=true;brokerLastAttempt=Date.now();brokerError='';render();try{const result=await brokerAPI({...brokerSession,action:'dividends',cursor:state.broker.nextCursor,accountId:state.broker.accountId});if(!secureSession.current(generation))return;mergeBrokerDividends(result.items);state.broker.nextCursor=result.nextCursor;state.broker.historyLoaded=true;save();toast('Older payments loaded');}catch(e){if(!secureSession.current(generation))return;brokerError=e.message;if(e.status===401||e.status===403){secureSession.clear();brokerSession=null;}}finally{brokerBusy=false;render();refresh();}});
}

function accountLabel(id){if(id==='all')return 'All accounts';if(id==='manual'||!id)return 'Manual portfolio';if(id==='trading212')return 'Trading 212';const account=xtbAccountDetails(id);return account?'XTB '+(account.accountType==='ike'?'IKE':'Standard')+(account.currency?' · '+account.currency:'')+' · '+account.accountRef:id;}
function registeredXtbAccounts(){return (Array.isArray(state.xtbAccounts)?state.xtbAccounts:[]).filter(a=>a&&xtbAccountDetails(a.accountId)?.currency);}
function accountSelector(){const ids=[...new Set([...state.transactions.map(t=>t.accountId||(t.source==='trading212'?'trading212':'manual')),...registeredXtbAccounts().map(a=>a.accountId)])];if(state.broker&&!ids.includes('trading212'))ids.push('trading212');if(!ids.includes(accountFilter)&&accountFilter!=='all')accountFilter='all';return `<div class="portfolio-scope"><div class="account-tabs" role="group" aria-label="Portfolio accounts">${['all',...ids].map(id=>`<button type="button" data-account-choice="${esc(id)}" aria-pressed="${accountFilter===id}">${esc(id==='all'?'All investments':accountLabel(id))}</button>`).join('')}</div><label class="mobile-account" for="account-filter">Account <select id="account-filter">${['all',...ids].map(id=>`<option value="${esc(id)}" ${id===accountFilter?'selected':''}>${esc(accountLabel(id))}</option>`).join('')}</select></label><span class="scope-meta">${ids.length} account${ids.length===1?'':'s'} · ${esc(state.base)}${fxInfo?' · FX '+esc(fxInfo.date):''}</span></div>`;}

function activeTransactions(){return state.transactions.filter(t=>accountFilter==='all'||(t.accountId||(t.source==='trading212'?'trading212':'manual'))===accountFilter);}
function openXtb(){resetXtbSelection();$('#xtb-import-form').reset();$('#xtb-output').innerHTML='';$('#xtb-options').hidden=true;$('#xtb-error').textContent='';$('#xtb-file').value='';$('#xtb-dialog').showModal();}
function xtbOptions(){const form=$('#xtb-import-form');const mappings={};document.querySelectorAll('[data-xtb-symbol]').forEach(input=>{const raw=input.dataset.xtbSymbol;mappings[raw]={symbol:input.value.trim().toUpperCase(),currency:document.querySelector('[data-xtb-currency="'+CSS.escape(raw)+'"]').value};});return {accountType:form.elements.accountType.value,accountRef:form.elements.accountRef.value.trim(),currency:form.elements.accountCurrency.value,mappings:{...(xtbQueue[xtbQueueIndex]?.options.mappings||{}),...mappings}};}
function showXtbPreview(){try{const options=xtbOptions();if(xtbQueue[xtbQueueIndex]){xtbQueue[xtbQueueIndex].options=options;const errors=xtbDestinationErrors(xtbQueue[xtbQueueIndex]);if(errors.length)throw Error(errors.join(' '));}xtbPreview=parseXtbSheets(xtbLoaded.sheets,options);let merged=null,mergeError='';try{merged=mergeXtbTransactions(state.demo?[]:state.transactions,xtbPreview);}catch(e){mergeError=e.message;}const p=xtbPreview;p.warnings=[...(xtbLoaded.metadata.warnings||[]),...p.warnings];$('#xtb-error').textContent='';$('#xtb-output').innerHTML=`<h3>Import preview · ${esc(accountLabel(p.accountId))}</h3><p class="muted">${esc(xtbLoaded.fileName)} · account currency ${esc(p.currency)}</p><div class="broker-summary"><span class="pill">${merged?.added??p.transactions.length} new records</span><span class="pill">${merged?.duplicates??0} duplicates</span><span class="pill">${merged?.updated??0} updates</span><span class="pill estimated">${p.ignored.length} excluded rows</span><span class="pill">${p.included?.length||0} sale-profit components included</span></div><p class="annual-note">${p.reconciliation?.status.startsWith('matched')?`Share counts reconciled with the statement (${p.reconciliation.positions} open instruments). `:p.reconciliation?.status==='mismatch'?'Position mismatch: review the issues below. ':'No open-position snapshot available for reconciliation. '}Trade cost and sale proceeds use the actual cash amount in the account currency, including the recorded conversion. Market prices use each instrument’s trading currency. IKE imports keep any withholding tax actually reported; the importer never invents a tax exemption.</p>${p.errors.length?`<div class="import-issues" role="alert"><strong>Resolve ${p.errors.length} issue(s)</strong><ul>${p.errors.slice(0,30).map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}${mergeError&&!p.errors.length?`<div class="import-issues" role="alert">${esc(mergeError)}. Export the full history since account opening, including buys preceding sales.</div>`:''}${p.warnings.length?`<p class="annual-note">${p.warnings.map(esc).join('<br>')}</p>`:''}<details ${p.errors.length?'open':''}><summary>Review market symbols and currencies</summary><p class="muted">Confirm exchange and trading currency. Changes apply when you click Preview again.</p>${p.symbols.map(m=>`<div class="xtb-map"><strong>${esc(m.raw)}</strong><input data-xtb-symbol="${esc(m.raw)}" value="${esc(m.symbol)}" aria-label="Market symbol for ${esc(m.raw)}"><select data-xtb-currency="${esc(m.raw)}" aria-label="Instrument currency for ${esc(m.raw)}"><option value="">Choose</option>${['USD','EUR','GBP','PLN','CHF','CAD','JPY','AUD','SEK','DKK'].map(c=>`<option ${c===m.currency?'selected':''}>${c}</option>`).join('')}</select></div>`).join('')}</details><div class="table-wrap import-table"><table class="data-table"><thead><tr><th>Asset / action</th><th>Date</th><th>Shares</th><th>Cash amount</th><th>Tax / fees</th></tr></thead><tbody>${p.transactions.slice(0,100).map(t=>`<tr><td>${esc(t.symbol)} · ${esc(t.incomeKind==='tax-refund'?'tax refund':t.incomeKind==='dividend-reversal'?'dividend reversal':t.type)}</td><td>${date(t.date)}</td><td>${isDividendIncome(t)?'—':num(t.quantity)}</td><td>${money(isDividendIncome(t)?t.amount:t.quantity*t.price,t.currency)}</td><td>${money(t.tax+t.fees,t.currency)}</td></tr>`).join('')}</tbody></table></div>${p.transactions.length>100?'<p class="muted">Showing the first 100 records.</p>':''}<details><summary>Excluded rows (${p.ignored.length})</summary><p class="muted">Deposits, withdrawals, IKE transfers/transfer taxes, FX, interest and identified CFD activity are excluded from equity totals. Equity sale-profit components are included through the matched sale values, not added twice.</p><ul class="excluded-list">${p.ignored.slice(0,100).map(r=>`<li>${esc(r.row)} · ${esc(r.type)}: ${esc(r.reason)}</li>`).join('')}</ul></details><button type="button" id="xtb-commit" class="primary wide" ${!merged||!p.transactions.length?'disabled':''}>${state.demo?'Replace example data and import':xtbQueue.length>1?'Import this statement & continue':'Import into '+esc(accountLabel(p.accountId))}</button>`;$('#xtb-commit').onclick=()=>{try{const currentOptions=xtbOptions();const latest=parseXtbSheets(xtbLoaded.sheets,currentOptions);if(JSON.stringify(latest.transactions)!==JSON.stringify(xtbPreview.transactions))throw Error('Options or mappings changed. Preview again before importing.');const result=mergeXtbTransactions(state.demo?[]:state.transactions,latest);const previous=state.transactions;state.transactions=result.transactions;try{localStorage.setItem(KEY,JSON.stringify({...state,demo:false}));}catch{state.transactions=previous;throw Error('Storage is full or unavailable. Export a backup and free space before importing.');}state.demo=false;accountFilter=latest.accountId;quotes={};render();refresh();toast(`Imported ${result.added} new records; ${result.duplicates} duplicates skipped; ${result.updated} updated.`);finishXtbStatement(result);}catch(e){$('#xtb-error').textContent=e.message;}};}catch(e){$('#xtb-error').textContent=e.message;$('#xtb-output').innerHTML='';xtbPreview=null;}}
function bindXtb(){$('#xtb-open')?.addEventListener('click',openXtb);}
function resetXtbSelection(){xtbReadVersion++;xtbLoaded=null;xtbPreview=null;xtbQueue=[];xtbSkipped=[];xtbQueueIndex=-1;$('#xtb-selection').innerHTML='';$('#xtb-batch').innerHTML='';$('#xtb-file').value='';$('#xtb-folder').value='';}
function renderXtbSelection(){const imported=xtbQueue.filter(e=>e.status==='imported').length;$('#xtb-selection').innerHTML=`${xtbQueue.length?`<div class="xtb-selection-head"><strong>${xtbQueue.length} XTB statements found</strong><span>${imported} imported · ${xtbQueue.length-imported} remaining</span></div><div class="xtb-file-list">${xtbQueue.map((entry,i)=>`<button type="button" class="xtb-file-entry ${i===xtbQueueIndex?'active':''}" data-xtb-entry="${i}" ${entry.status==='imported'?'disabled':''}><span>${esc(entry.displayName)}<small>${esc(entry.options.accountRef||'Confirm account reference')} · ${entry.options.accountType?entry.options.accountType==='ike'?'IKE':'Standard':'Confirm account type'} · ${esc(entry.options.currency||'Confirm cash currency')}</small></span><span class="pill">${entry.status==='imported'?'Imported':i===xtbQueueIndex?'Reviewing':'Review'}</span></button>`).join('')}</div>`:''}${xtbSkipped.length?`<details class="xtb-scan-skipped"><summary>${xtbSkipped.length} skipped file${xtbSkipped.length===1?'':'s'}</summary><ul>${xtbSkipped.slice(0,100).map(e=>`<li><strong>${esc(e.name)}</strong>: ${esc(e.reason)}</li>`).join('')}</ul>${xtbSkipped.length>100?'<p>Showing the first 100 skipped files.</p>':''}</details>`:''}`;document.querySelectorAll('[data-xtb-entry]').forEach(button=>button.onclick=()=>selectXtbStatement(Number(button.dataset.xtbEntry)));}
function selectXtbStatement(index){if(xtbQueue[xtbQueueIndex]&&xtbLoaded)xtbQueue[xtbQueueIndex].options=xtbOptions();const entry=xtbQueue[index];if(!entry||entry.status==='imported')return;xtbQueueIndex=index;xtbLoaded=entry.loaded;xtbPreview=null;$('#xtb-output').innerHTML='';$('#xtb-error').textContent='';const form=$('#xtb-import-form');form.elements.accountRef.value=entry.options.accountRef;form.elements.accountType.value=entry.options.accountType;form.elements.accountCurrency.value=entry.options.currency;$('#xtb-options').hidden=false;$('#xtb-account-caption').textContent='Account for '+entry.loaded.fileName;renderXtbSelection();if(form.elements.accountRef.checkValidity()&&form.elements.accountType.checkValidity()&&form.elements.accountCurrency.checkValidity())showXtbPreview();else $('#xtb-error').textContent=[...(entry.loaded.metadata.warnings||[]),'Confirm the account type, account number and cash currency, then preview this statement.'].join(' ');renderXtbBatchPreview();}
function finishXtbStatement(result){const entry=xtbQueue[xtbQueueIndex];if(entry){entry.status='imported';entry.result=result;}xtbLoaded=null;xtbPreview=null;const next=xtbQueue.findIndex(e=>e.status==='pending');if(xtbQueue.length===1){$('#xtb-dialog').close();return;}if(next>=0){selectXtbStatement(next);return;}$('#xtb-options').hidden=true;$('#xtb-error').textContent='';renderXtbSelection();renderXtbBatchPreview();$('#xtb-output').innerHTML=`<div class="read-only-note"><strong>All ${xtbQueue.length} detected statements imported.</strong><p>${xtbQueue.reduce((n,e)=>n+(e.result?.added||0),0)} new records saved. ${xtbQueue.reduce((n,e)=>n+(e.result?.duplicates||0),0)} overlapping records skipped. ${xtbSkipped.length} file${xtbSkipped.length===1?' was':'s were'} skipped during scanning; review the list above.</p></div><button type="button" id="xtb-done" class="primary wide">Done</button>`;$('#xtb-done').onclick=()=>$('#xtb-dialog').close();}
async function loadXtbSelection(files){if(!files.length)return;resetXtbSelection();const readVersion=xtbReadVersion;$('#xtb-output').innerHTML='';$('#xtb-options').hidden=true;$('#xtb-error').textContent='Scanning selected files…';try{const found=await scanXtbSelection(files,readXtbFile,{isCurrent:()=>readVersion===xtbReadVersion,onProgress:p=>{if(readVersion===xtbReadVersion)$('#xtb-error').textContent=`Reading ${p.index} of ${p.total}: ${p.name}`;}});if(found.cancelled||readVersion!==xtbReadVersion)return;xtbQueue=found.entries;for(const entry of xtbQueue){if(!entry.options.currency&&!entry.loaded.metadata.currencyConflict){const currencies=[...new Set(state.transactions.filter(t=>t.source==='xtb'&&t.accountType===entry.options.accountType&&t.accountRef===entry.options.accountRef).map(t=>t.currency))];if(currencies.length===1)entry.options.currency=currencies[0];}}xtbSkipped=found.skipped;renderXtbSelection();if(xtbQueue.length>1){$('#xtb-error').textContent='';renderXtbBatchPreview();}else if(xtbQueue.length)selectXtbStatement(0);else $('#xtb-error').textContent='No supported XTB statements found. Choose original XLSX or Cash Operations CSV exports.';}catch(e){if(readVersion===xtbReadVersion)$('#xtb-error').textContent=e.message;}}
function renderXtbBatchPreview(){
 const pending=xtbQueue.filter(e=>e.status!=='imported');if(xtbQueue.length<2||!pending.length){$('#xtb-batch').innerHTML='';return;}
 if(xtbLoaded&&xtbQueue[xtbQueueIndex])xtbQueue[xtbQueueIndex].options=xtbOptions();
 const batch=prepareXtbBatch(state.demo?[]:state.transactions,xtbQueue);
 $('#xtb-batch').innerHTML=`<div class="xtb-batch-box"><div class="panel-head"><div><h3>Import all accounts together</h3><p class="muted">Each statement keeps its own account type, number and cash currency.</p></div><div class="xtb-batch-actions"><span class="pill">${batch.accounts.length} accounts</span><button type="button" id="xtb-import-all-top" class="primary" ${batch.ready?'':'disabled'}>Import all ${batch.files.length}</button></div></div><div class="xtb-batch-destinations">${batch.files.map(f=>{const entry=xtbQueue[f.index],o=entry.options;return `<div class="xtb-batch-destination"><strong>${esc(entry.loaded.fileName)}</strong><div class="xtb-batch-fields"><label>Account type<select data-batch-entry="${f.index}" data-batch-field="accountType"><option value="" ${!o.accountType?'selected':''}>Choose account type</option><option value="regular" ${o.accountType==='regular'?'selected':''}>Standard</option><option value="ike" ${o.accountType==='ike'?'selected':''}>IKE</option></select></label><label>Account number<input data-batch-entry="${f.index}" data-batch-field="accountRef" value="${esc(o.accountRef)}" maxlength="64"></label><label>Cash currency<select data-batch-entry="${f.index}" data-batch-field="currency"><option value="" ${!o.currency?'selected':''}>Choose cash currency</option>${CURRENCIES.map(c=>`<option ${o.currency===c?'selected':''}>${c}</option>`).join('')}</select></label></div><small class="${f.errors.length?'negative':'muted'}">${f.errors.length?esc(f.errors[0]):`${f.preview.transactions.length} investment record${f.preview.transactions.length===1?'':'s'} · ready${entry.loaded.metadata.warnings?.length?' · source warning available under Review':''}`}</small></div>`;}).join('')}</div>${batch.errors.some(e=>e.index===null)?`<div class="import-issues">${batch.errors.filter(e=>e.index===null).map(e=>esc(e.error)).join('<br>')}</div>`:''}<div class="xtb-batch-summary">${batch.ready?`${batch.result.added} new records · ${batch.result.duplicates} duplicates skipped · ${batch.accounts.length} separate accounts`:'Resolve the account details or statement issues shown above. Use Review for row details and symbol mappings.'}</div><button type="button" id="xtb-import-all" class="primary wide" ${batch.ready?'':'disabled'}>${state.demo?'Replace example data and import all '+batch.files.length+' statements':'Import all '+batch.files.length+' statements into '+batch.accounts.length+' accounts'}</button><p class="annual-note">The batch is saved together after every statement passes validation. Received dividend and trade records remain assigned to their own account.</p></div>`;
 document.querySelectorAll('[data-batch-field]').forEach(input=>input.onchange=()=>{if(xtbLoaded&&xtbQueue[xtbQueueIndex])xtbQueue[xtbQueueIndex].options=xtbOptions();const index=Number(input.dataset.batchEntry),field=input.dataset.batchField,value=input.value.trim();xtbQueue[index].options[field]=value;if(index===xtbQueueIndex&&xtbLoaded){const form=$('#xtb-import-form');form.elements[field==='currency'?'accountCurrency':field].value=value;$('#xtb-output').innerHTML='';xtbPreview=null;}renderXtbSelection();renderXtbBatchPreview();});
 $('#xtb-import-all').onclick=importXtbBatch;$('#xtb-import-all-top').onclick=importXtbBatch;
}
function importXtbBatch(){
 try{if(xtbLoaded&&xtbQueue[xtbQueueIndex])xtbQueue[xtbQueueIndex].options=xtbOptions();const batch=prepareXtbBatch(state.demo?[]:state.transactions,xtbQueue);if(!batch.ready){renderXtbBatchPreview();return;}const next=createXtbBatchState(state,batch);try{localStorage.setItem(KEY,JSON.stringify(next));}catch{throw Error('Storage is full or unavailable. No statements in this batch were imported.');}state=next;for(const f of batch.files)xtbQueue[f.index].status='imported';xtbLoaded=null;xtbPreview=null;xtbQueueIndex=-1;$('#xtb-options').hidden=true;$('#xtb-error').textContent='';renderXtbSelection();renderXtbBatchPreview();$('#xtb-output').innerHTML=`<div class="read-only-note"><strong>Imported ${batch.files.length} statements into ${batch.accounts.length} separate accounts.</strong><p>${batch.result.added} new records · ${batch.result.duplicates} duplicates skipped · ${batch.result.updated} updated records.</p></div><button type="button" id="xtb-done" class="primary wide">Done</button>`;$('#xtb-done').onclick=()=>$('#xtb-dialog').close();accountFilter='all';quotes={};render();refresh();toast('Batch imported into '+batch.accounts.length+' separate accounts.');}catch(e){$('#xtb-error').textContent=e.message;}
}
