function currencyOptions(selected){return CURRENCIES.map(c=>`<option value="${c}" ${c===selected?'selected':''}>${c}</option>`).join('');}
function currencyView(){return `<div class="two-col"><div class="panel"><div class="panel-head"><div><h2>Quick conversion</h2><p class="muted">Daily reference exchange rates</p></div><span class="pill ${fxInfo?.stale?'estimated':''}">${fxInfo?esc(fxInfo.date)+(fxInfo.stale?' · cached':''):'Loading rates'}</span></div><form id="fx-converter"><label class="fx-label">Amount<input name="amount" type="number" min="0" max="1000000000000" step="any" value="${esc(converter.amount)}" required></label><div class="fx-currencies"><label class="fx-label">From<select name="from">${currencyOptions(converter.from)}</select></label><button type="button" id="fx-swap" class="icon-button" aria-label="Swap currencies">⇄</button><label class="fx-label">To<select name="to">${currencyOptions(converter.to)}</select></label></div><div id="fx-result" class="fx-result" aria-live="polite"></div><p id="fx-rate" class="muted"></p></form><p class="annual-note">Indicative reference rates from Frankfurter, updated daily and cached hourly. Your broker or bank may apply a different rate, spread or fee.</p></div><div class="panel"><div class="panel-head"><h2>Portfolio display currency</h2><span class="pill">PLN default</span></div><p class="health-text">Your selected currency converts holdings, market values, returns, received dividends and forecasts. The header selector saves your choice on this device.</p><label class="fx-label">Display currency<select id="display-currency">${currencyOptions(state.base)}</select></label><p class="annual-note">Original transaction amounts and statement currencies are retained. Asset charts use the selected currency at current daily FX; they do not include historical exchange-rate changes.</p></div></div><div class="panel"><div class="panel-head"><h2>Reference rates · 1 ${esc(state.base)}</h2><span class="muted">${fxInfo?'As of '+esc(fxInfo.date):'Rates unavailable'}</span></div><div class="fx-rate-grid">${CURRENCIES.filter(c=>c!==state.base).map(c=>`<div class="fx-rate-card"><span class="muted">${esc(c)}</span><strong>${fx[state.base]?.[c]?new Intl.NumberFormat('en',{maximumFractionDigits:6}).format(fx[state.base][c]):'—'}</strong></div>`).join('')}</div></div>`;}
function updateConverter(){const form=$('#fx-converter');if(!form)return;converter={amount:form.elements.amount.value,from:form.elements.from.value,to:form.elements.to.value};const amount=Number(converter.amount),valid=converter.amount.trim()!==''&&Number.isFinite(amount)&&amount>=0&&amount<=1e12,result=valid?convert(amount,converter.from,converter.to,fx):null;$('#fx-result').textContent=valid?result===null?'Rate unavailable':money(result,converter.to):'Enter a valid nonnegative amount';const rate=convert(1,converter.from,converter.to,fx);$('#fx-rate').textContent=rate===null?'Refresh to retrieve exchange rates.':`1 ${converter.from} = ${new Intl.NumberFormat('en',{maximumFractionDigits:6}).format(rate)} ${converter.to}${fxInfo?.stale?' · cached rate':''}`;}
function bindCurrencies(){const form=$('#fx-converter');if(form){form.onsubmit=e=>e.preventDefault();form.oninput=updateConverter;form.onchange=updateConverter;$('#fx-swap').onclick=()=>{const from=form.elements.from.value;form.elements.from.value=form.elements.to.value;form.elements.to.value=from;updateConverter();};updateConverter();}$('#display-currency')?.addEventListener('change',e=>{state.base=e.target.value;save();render();refresh();});}

window.addEventListener('pagehide',()=>{secureSession.clear();brokerSession=null;document.querySelectorAll('#broker-form input').forEach(input=>input.value='');});

window.addEventListener('pageshow',event=>{if(event.persisted)render();});

async function forgetSavedConnection(){if(!brokerSaved.available)brokerSaved=await brokerAPI({action:'connection-status'});if(brokerSaved.available)brokerSaved=await brokerAPI({action:'forget'});}
async function restoreSavedConnection(){const generation=secureSession.version;try{const status=await brokerAPI({action:'connection-status'});if(!secureSession.current(generation))return;brokerSaved=status;if(status.saved){secureSession.connected({useSaved:true},generation);brokerSession=secureSession.credentials;render();await syncBroker();}else if(view==='connections')render();}catch{if(view==='connections')render();}}
restoreSavedConnection();

setInterval(()=>{if(!document.hidden&&view==='overview'&&performanceRange===1){loadIntraday(true);loadBenchmark(true);}},60000);
